import math
from math import gcd

def squarefree_decomposition(D):
    n = D
    t = 1
    f = 2
    while f * f <= n:
        cnt = 0
        while n % f == 0:
            n //= f
            cnt += 1
        if cnt >= 2:
            t *= f ** (cnt // 2)
        f += 1 if f == 2 else 2
    return t, n

def verifier(assign):
    # Validate keys
    required = ['ab_len', 'cd_len', 'leg_len', 'r_ab', 'r_cd']
    for k in required:
        if k not in assign:
            # missing key
            return (False, None)
        if not isinstance(assign[k], int):
            return (False, None)
    AB = assign['ab_len']
    CD = assign['cd_len']
    l = assign['leg_len']
    RA = assign['r_ab']
    RC = assign['r_cd']
    if AB <= CD or AB <= 0 or CD <= 0 or l <= 0 or RA <= 0 or RC <= 0:
        return (False, None)
    if AB % 2 != 0 or CD % 2 != 0:
        return (False, None)
    a = AB // 2
    c = CD // 2
    if not (a > c):
        return (False, None)
    delta = a - c
    h2 = l * l - delta * delta
    if h2 <= 0:
        return (False, None)
    if RA == RC:
        return (False, None)
    # Build coefficients
    S = RC - RA
    E = RA + RC
    U = 2 * S
    T = c * c - a * a + h2
    V = S * E - T
    A = U * U - 4 * h2
    if A == 0:
        return (False, None)
    Bc = 2 * U * V - 8 * h2 * RA
    Cc = V * V + 4 * h2 * (a * a - RA * RA)
    Delta = Bc * Bc - 4 * A * Cc
    if Delta <= 0:
        return (False, None)
    s = int(math.isqrt(Delta))
    if s * s == Delta:
        # too easy (rational)
        return (False, None)
    denom = 2 * A
    h = math.sqrt(h2)
    z_plus = (-Bc + math.sqrt(Delta)) / denom
    z_minus = (-Bc - math.sqrt(Delta)) / denom
    candidates = [z_plus, z_minus]
    valid_root = None
    valid_sign = None
    for idx, z in enumerate(candidates):
        if z <= 1e-9:
            continue
        y = (S * (2 * z + E) - T) / (2 * h)
        if not (-h < y < 0):
            continue
        # containment
        if z > -y + 1e-8:
            continue
        if z > (y + h) + 1e-8:
            continue
        leg_dist = abs(delta * y + h * a) / math.sqrt(h2 + delta * delta)
        if z > leg_dist + 1e-8:
            continue
        dA = math.hypot(a, y)
        dC = math.hypot(c, y + h)
        if abs(dA - (z + RA)) > 2e-6:
            continue
        if abs(dC - (z + RC)) > 2e-6:
            continue
        valid_root = z
        valid_sign = +1 if idx == 0 else -1
        break
    if valid_root is None:
        return (False, None)
    # Build the canonical (-k + m sqrt(n))/p representation with k,m,p>0 and gcd(k,p)=1
    R0 = -Bc
    D0 = 2 * A
    sgn = valid_sign
    if D0 < 0:
        D0 = -D0
        R0 = -R0
        sgn = -sgn
    t_raw, n_sf = squarefree_decomposition(Delta)
    d = gcd(gcd(abs(R0), abs(D0)), t_raw)
    if d == 0:
        return (False, None)
    u_prime = R0 // d
    m_prime = t_raw // d
    p_prime = D0 // d
    # Ensure it matches chosen root
    r_check = (u_prime + sgn * m_prime * math.sqrt(n_sf)) / p_prime
    if abs(r_check - valid_root) > 1e-6:
        return (False, None)
    # Now enforce k,m,p>0 and gcd(k,p)=1 with the target shape (-k + m sqrt n)/p.
    # This requires u' < 0, m' > 0, p' > 0 and gcd(|u'|, p') = 1.
    if not (u_prime < 0 and m_prime > 0 and p_prime > 0 and gcd(abs(u_prime), p_prime) == 1):
        return (False, None)
    k = -u_prime
    m = m_prime
    n = n_sf
    p = p_prime
    # Return the requested sum
    answer = k + m + n + p
    return True, answer
